-- ============================================================
-- SEED EXT 6: Módulo 15 — Gerund & Infinitive (ex 217-300)
-- Tópicos: verbos que mudam de sentido, gerúndio como sujeito,
-- infinitivo de propósito, estruturas formais avançadas, TOEFL integrado
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'gerund-infinitive';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo gerund-infinitive não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: Verbos que mudam de sentido (remember/forget/stop/try/regret)
  (cid,71,217,'gap_fill','The commission _____ (regret) _____ (inform) stakeholders that the proposed timeline _____ (have/to/revise) — a decision it _____ (try) _____ (avoid) _____ (make) for several months.','regrets / informing / has to be revised / had tried / to avoid / making',NULL,'''Regrets informing'' = formal apology for present action; ''try to avoid making'' = infinitive of effort.','hard'),
  (cid,71,218,'gap_fill','She _____ (remember) _____ (receive) a similar proposal three years earlier, though she _____ (forget) _____ (document) the rationale that had led to its rejection — an oversight she _____ (regret) _____ (make).','remembered / receiving / had forgotten / to document / regretted / making',NULL,'''Remembered receiving'' = recall of past event; ''forgotten to document'' = failed to do; ''regretted making'' = past action regret.','hard'),
  (cid,71,219,'gap_fill','The organization _____ (stop) _____ (publish) quarterly reports in order _____ (concentrate) resources on _____ (produce) a single comprehensive annual review, though some stakeholders _____ (stop) _____ (read) the reports long before that decision.','stopped / publishing / to concentrate / producing / had stopped / reading',NULL,'''Stopped publishing'' = ceased; ''to concentrate'' = infinitive of purpose; ''stopped reading'' = ceased activity.','hard'),
  (cid,71,220,'gap_fill','The researcher _____ (try) _____ (replicate) the original findings but _____ (fail), so she _____ (try) _____ (adjust) the methodology — _____ (mean) she _____ (attempt) _____ (rescue) results that _____ (resist) _____ (challenge) to.','tried / to replicate / failed / tried / adjusting / meaning / attempted / to rescue / were resistant / being challenged',NULL,'''Tried to replicate'' = attempt; ''tried adjusting'' = experiment; ''resist being challenged'' = gerund after preposition.','hard'),
  (cid,71,221,'multiple_choice','Which sentence MOST correctly uses ''stop'' with the right form?','The committee stopped reviewing proposals to take a short break, but the chair had not stopped thinking about the implications.','["The committee stopped to review proposals to take a short break.","The committee stopped reviewing proposals to take a short break, but the chair had not stopped thinking about the implications.","The committee stopped reviewing proposals for taking a short break.","The committee stopped to reviewing proposals to take a short break."]','''Stopped reviewing'' = ceased the activity; ''to take'' = purpose; ''stopped thinking'' = ceased thinking — both correctly differentiated.','medium'),
  (cid,71,222,'gap_fill','The policy document _____ (go on) _____ (argue) that fiscal constraints _____ (prevent) the government from _____ (invest) adequately in _____ (build) _____ (the) _____ institutional _____ capacity _____ (require/passive) _____ (sustain) reform.','went on / to argue / prevented / investing / building / the / institutional / capacity / required / to sustain',NULL,'''Go on to argue'' = continue in new direction; ''prevent from investing''; ''required to sustain'' = infinitive of purpose.','hard'),
  (cid,71,223,'gap_fill','He _____ (mean) _____ (raise) the issue at the meeting but _____ (run out) of time; the delay _____ (mean) _____ (lose) the window for _____ (address) it before the decision _____ (finalize/passive).','meant / to raise / ran out / meant / losing / addressing / was finalized',NULL,'''Meant to raise'' = intended; ''meant losing'' = resulted in; ''address before finalized'' = gerund after preposition.','hard'),
  (cid,71,224,'gap_fill','The board _____ (forget) _____ (include) an agenda item on governance reform, _____ (force) members who _____ (remember) _____ (hear) a similar proposal rejected to _____ (raise) it from the floor.','had forgotten / to include / forcing / remembered / hearing / raise',NULL,'''Forgotten to include'' = failed to do; ''remembered hearing'' = recall of past; ''raise from floor'' = bare infinitive after ''force.''','hard'),

  -- BLOCK 72: Gerúndio como sujeito em argumentação formal
  (cid,72,225,'gap_fill','_____ (design) institutions that are simultaneously effective and accountable _____ (require) navigating genuine trade-offs — _____ (prioritize) one _____ (tend) to _____ (undermine) the other unless _____ (build) _____ (careful) _____ (safeguard) _____ (prevent) this.','Designing / requires / prioritizing / tends / undermine / careful safeguards are built to / prevent',NULL,'''Designing requires'' + ''prioritizing tends to undermine'' = gerund subjects for institutional analysis.','hard'),
  (cid,72,226,'gap_fill','_____ (fail) _____ (acknowledge) the limitations of one''s method is not merely an intellectual failure — _____ (present) _____ (find) as more certain than they are _____ (mislead) policymakers into _____ (make) _____ (decision) on a weaker evidential basis than they realize.','Failing / to acknowledge / presenting / findings / misleads / making / decisions',NULL,'''Failing to acknowledge'' + ''presenting findings'' as subjects; ''misleads into making decisions.''','hard'),
  (cid,72,227,'gap_fill','_____ (resist) _____ (change) is not always a sign of _____ (be) _____ (recalcitrant) — _____ (ensure) _____ (any) change _____ (be) _____ (well-consider) before _____ (implement/passive) _____ (prevent) the kind of _____ (rash) decision-_____ (make) that _____ (generate) costly reversals.','Resisting / change / being / recalcitrant / ensuring / any / change / is well-considered / before / being implemented / prevents / rash / making / generates',NULL,'''Resisting change is not always a sign of being recalcitrant'' + ''ensuring is well-considered'' for institutional caution argument.','hard'),
  (cid,72,228,'gap_fill','_____ (balance) _____ (the) competing _____ (demand) of _____ (accountability) and _____ (autonomy) is one of the defining _____ (challenge) of institutional _____ (design) — _____ (get) it right _____ (require) _____ (attend) to context rather than _____ (apply) _____ (one-size-fits-all) solution.','Balancing / the / demands / accountability / autonomy / challenges / design / getting / requires / attending / applying / one-size-fits-all',NULL,'''Balancing demands requires attending'' for institutional design gerund argument.','hard'),
  (cid,72,229,'gap_fill','_____ (achieve) _____ (the) full potential of a reform _____ (depend) on _____ (secure) _____ (the) _____ (buy-in) of _____ (those) responsible for _____ (implement) it — and _____ (secure) that buy-in _____ (require) _____ (demonstrate) that the reform _____ (take) their concerns seriously.','Achieving / the / full potential / depends / securing / the / buy-in / those / implementing / securing / requires / demonstrating / takes',NULL,'''Achieving depends on securing'' + ''securing requires demonstrating'' for stakeholder engagement argument.','hard'),
  (cid,72,230,'multiple_choice','Which gerund subject sentence is MOST effective in formal academic writing?','Maintaining consistent standards across multiple implementing agencies requires investing substantially in training, communication, and performance management systems.','["Maintain consistent standards requires investing substantially.","Consistently maintaining standards requires investing in training substantially.","Maintaining consistent standards across multiple implementing agencies requires investing substantially in training, communication, and performance management systems.","The maintaining of standards consistently requires investing substantially in training."]','Full gerund subject ''Maintaining consistent standards across multiple agencies'' + ''requires investing substantially'' = most precise and formal.','medium'),
  (cid,72,231,'gap_fill','_____ (invest) adequately in _____ (prevent) _____ (problem) is consistently cheaper than _____ (spend) the same resources on _____ (address) _____ (them) after they _____ (occur) — a principle _____ (acknowledge/widely) but _____ (apply/rarely) in institutional practice.','Investing / preventing / problems / spending / addressing / them / have occurred / widely acknowledged / rarely applied',NULL,'''Investing in preventing'' + ''spending on addressing'' + ''widely acknowledged but rarely applied.''','hard'),
  (cid,72,232,'gap_fill','_____ (understand) why _____ (reform) _____ (fail) _____ (require) more than _____ (catalog) what _____ (go wrong) — it _____ (require) _____ (explain) the _____ (mechanism) through which failures _____ (occur) and _____ (identify) what might have _____ (prevent) them.','Understanding / reforms / fail / requires / cataloguing / went wrong / requires / explaining / mechanisms / occur / identifying / prevented',NULL,'''Understanding why reforms fail requires explaining mechanisms'' for analytical depth argument.','hard'),

  -- BLOCK 73: Infinitivo de propósito e complemento
  (cid,73,233,'gap_fill','The institution _____ (establish/passive) _____ (provide) _____ (a) _____ neutral forum in which _____ (contest) claim _____ (resolve/can/passive) — _____ (not) _____ (adjudicate) disputes between powerful actors _____ (be) _____ (never/its) purpose.','was established / to provide / a / neutral / forum / contested / claims / can be resolved / not / to adjudicate / disputes / was never its purpose',NULL,'''Established to provide'' + ''not to adjudicate'' = infinitives of purpose in formal institutional description.','hard'),
  (cid,73,234,'gap_fill','The government _____ (commission) _____ (the) _____ report _____ (obtain) _____ (an) _____ independent _____ assessment, only _____ (find) _____ that the assessment _____ (challenge) _____ (the) _____ assumptions on which _____ (its) _____ proposal _____ (base/passive).','commissioned / the / report / to obtain / an / independent / assessment / to find / that / challenged / the / assumptions / its / proposal / was based',NULL,'''Commissioned to obtain'' + ''only to find'' (unexpected result) for institutional independence analysis.','hard'),
  (cid,73,235,'gap_fill','The framework _____ (design/passive) _____ (allow) for _____ (a) _____ degree of _____ (contextual) _____ adaptation, _____ (enable) _____ (implement) _____ (agency) to _____ (tailor) _____ (the) _____ approach _____ (suit) _____ (their) particular _____ circumstances without _____ (abandon) _____ (the) _____ core principles.','was designed / to allow / for / a / degree / contextual / adaptation / enabling / implementing / agencies / tailor / the / approach / to suit / their / circumstances / abandoning / the / core principles',NULL,'''Designed to allow'' + ''enabling agencies to tailor'' + ''without abandoning'' for flexible framework description.','hard'),
  (cid,73,236,'gap_fill','The decision _____ (delay) _____ (the) _____ announcement was taken _____ (avoid) _____ (create) _____ (unnecessary) _____ (alarm) before _____ (the) _____ government _____ (have) _____ (the) _____ information _____ (need/passive) _____ (make) an _____ (inform) _____ (statement).','to delay / the / announcement / to avoid / creating / unnecessary / alarm / before / the / government / had / the / information / needed / to make / an / informed / statement',NULL,'''To delay'' + ''to avoid creating alarm'' + ''needed to make an informed statement'' for communication decision analysis.','hard'),
  (cid,73,237,'gap_fill','The researchers _____ (return) _____ (the) _____ field _____ (collect) _____ (additional) _____ (data), only _____ (discover) that _____ (the) _____ community they had _____ (study) had _____ (undergo) significant _____ (change) since their initial _____ (visit).','returned / to the / field / to collect / additional / data / to discover / the / community / studied / had undergone / significant / change / visit',NULL,'''Returned to collect'' + ''only to discover'' + ''had undergone change'' for fieldwork narrative.','hard'),
  (cid,73,238,'multiple_choice','Which sentence MOST correctly uses the infinitive of purpose in academic writing?','The study was designed to examine whether the intervention produced lasting behavioral change.','["The study was designed for examining whether the intervention produced lasting behavioral change.","The study was designed in order for examining whether the intervention produced lasting behavioral change.","The study was designed to examine whether the intervention produced lasting behavioral change.","The study was designed so as examining whether the intervention produced lasting behavioral change."]','''Designed to examine'' = correct infinitive of purpose. ''For examining'' is informal. ''In order for examining'' and ''so as examining'' are ungrammatical.','easy'),
  (cid,73,239,'gap_fill','The policy _____ (intend/passive) _____ (achieve) _____ (the) _____ dual purpose of _____ (reduce) _____ (fiscal) _____ (deficit) while _____ simultaneously _____ (protect) _____ (the) _____ most _____ vulnerable from _____ (bear) _____ (a) _____ disproportionate _____ share of _____ (the) _____ adjustment _____ (burden).','was intended / to achieve / the / dual / purpose / reducing / fiscal / deficit / protecting / the / most / vulnerable / bearing / a / disproportionate / share / the / adjustment / burden',NULL,'''Intended to achieve the dual purpose of reducing...while protecting from bearing'' for policy design analysis.','hard'),
  (cid,73,240,'gap_fill','The committee _____ (convene) _____ (address) a range of _____ (concern) _____ (raise/passive) by _____ (member) _____ (state), _____ (aim) ultimately _____ (produce) _____ (a) _____ set of _____ (recommendation) _____ (acceptable) to _____ (all) _____ (party) involved.','convened / to address / concerns / raised / member / states / aiming / to produce / a / set / recommendations / acceptable / all / parties',NULL,'''Convened to address'' + ''aiming to produce recommendations acceptable to all parties.''','hard'),

  -- BLOCK 74: Gerúndio vs. infinitivo — distinções semânticas avançadas
  (cid,74,241,'gap_fill','The decision _____ (implement) the reform immediately, rather than _____ (phase) it in gradually, _____ (reflect) a judgment that the _____ (cost) of _____ (delay) _____ (outweigh) the _____ (risk) of _____ (move) too quickly.','to implement / phasing / reflected / costs / delay / outweighed / risks / moving',NULL,'''Decision to implement'' + ''rather than phasing'' + ''risk of moving'' for reform timing analysis.','hard'),
  (cid,74,242,'gap_fill','The organization _____ (commit) _____ (publish) its findings regardless of their implications — a commitment that _____ (prove) _____ (challenge) to _____ (honor) when the findings _____ (run) counter to _____ (the) _____ position of _____ (its) _____ primary funder.','committed / to publishing / proved / challenging / honor / ran / the / position / its / primary funder',NULL,'''Committed to publishing'' (gerund after to = preposition) + ''proved challenging to honor.''','hard'),
  (cid,74,243,'gap_fill','_____ (keep) _____ (promise) _____ (make/passive) _____ under _____ (pressure) _____ (require) _____ (same/the) institutional _____ commitment as _____ (keep) _____ those _____ (make/passive) _____ in _____ favorable _____ circumstances — if _____ (not) more, _____ given _____ (the) _____ _____ (cost) of _____ (maintain) consistency when it is costly.','Keeping / promises / made / under / pressure / requires / the same / institutional / commitment / keeping / those / made / in / favorable / circumstances / if not more / given / the / costs / maintaining',NULL,'''Keeping promises made under pressure requires keeping those made in favorable circumstances'' for institutional integrity argument.','hard'),
  (cid,74,244,'gap_fill','The capacity for _____ (learn) from _____ (fail) is arguably _____ (the) most important _____ (institutional) capability — _____ (develop) it _____ (require) _____ (create) _____ systems that _____ (encourage) _____ (report) _____ errors rather than _____ (conceal) them and that _____ (reward) _____ (reflect) on what _____ (go wrong).','learning / failure / the / institutional / developing / requires / creating / encourage / reporting / concealing / reward / reflecting / went wrong',NULL,'''Capacity for learning from failure'' + ''developing it requires creating systems that encourage reporting.''','hard'),
  (cid,74,245,'multiple_choice','Which sentence correctly distinguishes between gerund and infinitive after ''propose''?','The chair proposed adopting a new framework, while the secretary suggested a proposal to reconsider the existing one.','["The chair proposed to adopt a new framework, while the secretary suggested proposing to reconsider the existing one.","The chair proposed adopting a new framework, while the secretary suggested a proposal to reconsider the existing one.","The chair proposed to adopt a new framework, while the secretary suggested to reconsider the existing one.","The chair proposed adopting a new framework, while the secretary suggested to reconsider the existing one."]','''Proposed adopting'' = correct (propose + gerund in American English); ''a proposal to reconsider'' = noun phrase + infinitive.','medium'),
  (cid,74,246,'gap_fill','The government _____ (consider) _____ (withdraw) from the agreement before _____ (decide) _____ (negotiate) a revised set of terms — _____ (recognize) _____ that _____ (leave) entirely would carry greater reputational costs than _____ (stay) and _____ (push) for change from within.','considered / withdrawing / deciding / to negotiate / recognizing / leaving / staying / pushing',NULL,'''Considered withdrawing'' + ''deciding to negotiate'' + ''recognizing that leaving/staying and pushing'' for negotiation strategy analysis.','hard'),
  (cid,74,247,'gap_fill','_____ (avoid) _____ (duplicate) effort _____ (require) _____ (coordinate) across _____ (the) _____ implementing _____ agencies from the outset, rather than _____ (allow) each to _____ (develop) _____ (its) own systems and then _____ (attempt) _____ (reconcile) them afterward.','Avoiding / duplicating / requires / coordinating / the / implementing / allowing / develop / its / attempting / to reconcile',NULL,'''Avoiding duplicating requires coordinating'' + ''allowing each to develop'' + ''attempting to reconcile'' for coordination argument.','hard'),
  (cid,74,248,'gap_fill','The researchers _____ (resist) _____ (draw) _____ (strong) _____ (conclusion) from _____ (the) limited data, _____ (prefer) _____ (present) their findings as _____ (tentative) and _____ (invite) _____ (further) _____ (investigation) rather than _____ (claim) more _____ (certainty) than the evidence _____ (warrant).','resisted / drawing / strong / conclusions / the / preferring / presenting / tentative / inviting / further / investigation / claiming / certainty / warranted',NULL,'''Resisted drawing conclusions'' + ''preferring presenting as tentative'' + ''inviting investigation'' for epistemic humility.','hard'),

  -- BLOCK 75: TOEFL Reading — Gerúndio e infinitivo
  (cid,75,249,'multiple_choice','[TOEFL Reading] ''The board decided to suspend the program pending further review.'' The infinitive ''to suspend'' functions as:','The object of the verb ''decided.''','["The subject of the sentence","The object of the verb ''decided.''","An adverb modifying ''suspend''","The subject complement of ''suspend''"]','''Decided + infinitive'' = verb-infinitive complement. ''To suspend'' = object of ''decided.''','easy'),
  (cid,75,250,'gap_fill','[TOEFL Reading] ''The policy _____ (allow) for substantial discretion in _____ (implement) its provisions, which facilitated adaptation but also created opportunities for _____ (avoid) its most demanding requirements.'' Best forms?','allows / implementing / avoiding',NULL,'''Allows for implementing'' (gerund as object of for) + ''opportunities for avoiding'' (gerund after for).','medium'),
  (cid,75,251,'gap_fill','[TOEFL Reading] ''_____ (produce) results that are both rigorous and relevant is harder than _____ (acknowledge/passive) in most methodological discussions.'' Best forms?','Producing / is acknowledged',NULL,'''Producing results...is harder'' = gerund subject; ''is acknowledged'' = passive in main clause.','easy'),
  (cid,75,252,'multiple_choice','[TOEFL Reading] ''The organization committed to reducing its administrative overhead by 20 percent.'' The gerund ''reducing'' follows ''to'' because:','In this context, ''to'' is a preposition followed by a gerund, not part of an infinitive.','["It is a gerund infinitive construction","In this context, ''to'' is a preposition followed by a gerund, not part of an infinitive.","''Committed'' always takes an infinitive","''Reducing'' is the subject of the clause"]','''Committed to reducing'' = verb + prepositional phrase (''to'' as preposition) + gerund. ''Committed to reduce'' would be incorrect.','medium'),
  (cid,75,253,'gap_fill','[TOEFL Reading] ''The authors _____ (attempt) _____ (determine) whether the observed pattern was attributable to the intervention or to pre-existing differences between the groups.'' Best forms?','attempted / to determine',NULL,'''Attempted to determine'' = verb + infinitive complement (attempt always takes infinitive).','easy'),
  (cid,75,254,'gap_fill','[TOEFL Reading] ''The tendency _____ (attribute) _____ (positive) outcomes to _____ (one''s own/strategy) and _____ (negative) ones to _____ (external/factor) _____ (document/widely/passive) across domains.'' Best forms?','to attribute / positive / one''s own strategy / negative / external factors / is widely documented',NULL,'''Tendency to attribute'' (infinitive after noun) + ''is widely documented.''','medium'),
  (cid,75,255,'multiple_choice','[TOEFL Reading] ''The researchers needed additional data to substantiate their claims.'' The infinitive ''to substantiate'' expresses:','Purpose — they needed data in order to substantiate.','["Cause","Purpose — they needed data in order to substantiate.","Result","Subject complement"]','Infinitive of purpose after ''needed additional data.''','easy'),
  (cid,75,256,'gap_fill','[TOEFL Reading] ''_____ (succeed) in _____ (change) _____ (entrenched) behavior at scale _____ (require) much more than _____ (identify) the right incentives — it _____ (require) _____ (build) the capacity to _____ (deliver) them consistently.'' Best forms?','Succeeding / changing / entrenched / requires / identifying / requires / building / deliver',NULL,'''Succeeding in changing requires identifying'' + ''requires building'' for behavior change argument.','hard'),

  -- BLOCK 76: TOEFL Speaking — Gerúndio e infinitivo
  (cid,76,257,'production','[TOEFL Speaking — 45s] The professor discusses what distinguishes effective institutions. Use gerunds and infinitives throughout.','',NULL,'The professor argues that what distinguishes effective institutions is not primarily their formal design but their capacity to learn from experience. She emphasizes that succeeding in building institutional effectiveness requires more than establishing good rules — it requires developing cultures in which acknowledging failure is treated as an essential step toward improving performance, not as something to be concealed or minimized. She notes that many institutions resist admitting mistakes because doing so threatens the reputations of those responsible, and that changing this behavior demands creating systems that separate learning from blame. The professor concludes that the willingness to be transparent about what went wrong, to analyze the causes rigorously, and to adjust practice accordingly is what separates institutions capable of sustained improvement from those condemned to repeat their errors.','hard'),
  (cid,76,258,'production','[TOEFL Speaking — 45s] The reading and professor discuss an organization''s challenges. Use gerunds and infinitives throughout.','',NULL,'The reading and the professor both describe an organization struggling to balance the competing demands of accountability and operational effectiveness. The reading focuses on the structural tensions, arguing that designing systems to maximize accountability often means requiring extensive documentation and approval processes that slow down implementing decisions and make adapting to changing circumstances very difficult. The professor largely agrees but argues that the reading understates how much of the problem comes from misunderstanding what accountability means. She argues that true accountability involves taking responsibility for outcomes rather than just following procedures, and that reframing accountability in this way would allow organizations to eliminate many of the compliance requirements that add burden without improving outcomes while simultaneously strengthening the focus on actually achieving results. Her conclusion is that designing better accountability systems means deciding what genuinely matters and focusing measurement and oversight on those things, rather than trying to monitor everything and ending up understanding nothing.','hard'),
  (cid,76,259,'production','[TOEFL Speaking — 60s] Compare what the reading and professor say about how organizations learn, using gerunds and infinitives.','',NULL,'The reading and the professor agree that learning from experience is essential for organizational effectiveness, but they have quite different views on what makes it happen. The reading focuses on structures: establishing review processes, requiring after-action reports, and creating dedicated units responsible for capturing and disseminating lessons. It argues that building these structures is a necessary precondition for learning, and that attempting to improve organizational performance without investing in them is unlikely to succeed. The professor accepts this but argues that structures alone are insufficient. She observes that many organizations have invested heavily in creating learning infrastructure without actually improving their capacity to adapt, because the culture of the organization makes admitting failure too costly for the individuals involved. She argues that what matters most is creating incentives that make reporting problems and acknowledging what went wrong in the interest of those who experienced it, rather than treating such reporting as an admission of personal failure. She gives examples of organizations that managed to do this — to turn learning from experience from something that happened despite individual incentives into something that aligned with them — and argues that in each case, the key was demonstrating through concrete actions by senior leadership that acknowledging mistakes was valued and rewarded rather than penalized. Her conclusion is that building learning organizations requires attending to both structures and culture, and that neglecting either one makes succeeding at the other much harder.','hard'),
  (cid,76,260,'gap_fill','[TOEFL Speaking] The reading suggests that _____ (avoid) _____ (design) institutions with contradictory incentives is the primary challenge, while the professor argues that _____ (sustain) good performance over time _____ (require) _____ (continue) _____ (invest) in leadership development.','avoiding / designing / sustaining / requires / continuing / investing',NULL,'''Avoiding designing'' + ''sustaining requires continuing investing'' for reading/professor contrast.','medium'),

  -- BLOCK 77: TOEFL Writing — Gerúndio e infinitivo
  (cid,77,261,'production','[TOEFL Writing — 200 words] Write a paragraph on what makes evidence persuasive to policymakers, using gerunds and infinitives throughout.','',NULL,'Persuading policymakers to act on evidence requires understanding how they process information and make decisions in contexts characterized by uncertainty, competing priorities, and political pressure. Producing technically rigorous evidence is necessary but insufficient — communicating findings in ways that connect to the questions policymakers are actually trying to answer is equally important. Framing the evidence in terms of the outcomes that matter to decision-makers, rather than the methodological questions that matter to researchers, is often the difference between evidence that influences decisions and evidence that gets filed and forgotten. Presenting findings simply enough to be understood without sacrificing the nuances that affect how they should be applied is a genuine skill that most researchers have not been trained to develop. Timing matters as well: releasing findings when the policy window is open — when decision-makers are actively seeking information to inform a choice that is before them — is much more effective than attempting to influence decisions retrospectively. And building relationships with the analysts and officials who advise decision-makers, so that researchers are seen as credible and accessible sources rather than remote experts producing incomprehensible technical documents, is perhaps the most durable strategy for ensuring that evidence finds its way into policy. None of this guarantees that good evidence will be acted upon — but failing to attend to these factors almost guarantees that it will not be.','hard'),
  (cid,77,262,'production','[TOEFL Writing — 200 words] Write a body paragraph on what organizations must do to maintain their effectiveness over time, using gerunds and infinitives.','',NULL,'Maintaining organizational effectiveness over extended periods requires attending to several things simultaneously that tend to pull in different directions. Sustaining a clear focus on mission is essential — allowing the accumulation of activities that are peripheral to the core purpose gradually erodes the capacity for impact. But adapting the mission to evolving circumstances is equally necessary, because organizations that refuse to revise what they are trying to achieve in response to what they learn about what is possible become increasingly disconnected from the problems they are supposed to address. Managing this tension between staying focused and remaining adaptive requires developing judgment rather than following rules, which is why investing in leadership development is one of the highest-return uses of organizational resources. Beyond mission management, maintaining effectiveness requires continuously updating the skills and knowledge of the people responsible for delivering it — the knowledge base relevant to most organizational tasks evolves quickly enough that failing to invest in professional development gradually degrades capacity even when no one is actively making things worse. It also requires monitoring performance honestly: creating systems that detect declining effectiveness early enough to allow correction, rather than discovering problems only when they have become entrenched and visible. And it requires sustaining the relationships with stakeholders whose trust and cooperation make effectiveness possible, which means treating accountability not as a compliance burden to be managed but as a genuine obligation to be honored.','hard'),
  (cid,77,263,'gap_fill','[TOEFL Writing] _____ (maintain) _____ (the) _____ distinction between what is known and what is _____ (assume) _____ (be) the first obligation of _____ (rigorous) _____ (scholarship) — _____ (fail) _____ (do) so _____ (invite) _____ (the) _____ kind of _____ (overconfidence) that _____ (generate) misguided policy.','Maintaining / the / assumed / to be / rigorous / scholarship / failing / to do / invites / the / kind / overconfidence / generates',NULL,'''Maintaining distinction is the first obligation'' + ''failing to do invites overconfidence.''','hard'),
  (cid,77,264,'gap_fill','[TOEFL Writing] The _____ (attempt) _____ (reconcile) _____ (the) _____ _____ (conflicting) _____ (demand) of _____ (transparency) and _____ (operational) _____ (effectiveness) is among _____ (the) _____ most _____ (persist) _____ (challenge) in _____ (the) _____ design of _____ (public) _____ (institution).','attempt / to reconcile / the / conflicting / demands / transparency / operational / effectiveness / the / most / persistent / challenges / the / design / public / institutions',NULL,'''Attempt to reconcile conflicting demands'' = noun + infinitive complement for institutional design argument.','hard'),
  (cid,77,265,'gap_fill','[TOEFL Writing] _____ (argue) that _____ (the) _____ (structure) _____ (determine) _____ (outcome) is not the same as _____ (argue) that _____ (structure) is _____ (sufficient) _____ (determine) them — _____ (the) _____ former _____ (be) a claim about _____ (necessity), _____ (the) _____ latter about _____ (sufficiency).','Arguing / the / structures / determine / outcomes / arguing / structure / sufficient / to determine / the / former / is / necessity / the / latter / sufficiency',NULL,'''Arguing that structures determine outcomes'' + ''arguing that structure is sufficient to determine'' for analytical precision.','hard'),
  (cid,77,266,'gap_fill','[TOEFL Writing] The capacity for _____ (think) _____ (systematically) about _____ (complex) _____ (problem) _____ (develop/must/passive) rather than _____ (assume/passive) _____ (present/to be) — _____ (build) it _____ (require) _____ (expose) _____ (student) to _____ (challenge) _____ (problem) rather than _____ (allow) them _____ (learn) _____ (formulaic) _____ (response).','thinking / systematically / complex / problems / must be developed / assumed / to be present / building / requires / exposing / students / challenging / problems / allowing / to learn / formulaic / responses',NULL,'''Capacity for thinking systematically'' + ''must be developed'' + ''building requires exposing students'' + ''allowing to learn.''','hard'),
  (cid,77,267,'gap_fill','[TOEFL Writing] _____ (overlook) _____ (the) _____ _____ (interaction) _____ (between) _____ (structural) and _____ (cultural) _____ (factor) _____ (lead) to _____ (overestimate) _____ (the) _____ _____ (capacity) of _____ (reform) _____ (alone) _____ (produce) _____ lasting _____ (change).','Overlooking / the / interactions / between / structural / cultural / factors / leads / overestimating / the / capacity / reform / alone / to produce / lasting / change',NULL,'''Overlooking leads to overestimating the capacity of reform alone to produce'' for structural analysis argument.','hard'),
  (cid,77,268,'gap_fill','[TOEFL Writing] The _____ _____ (failure) _____ (take) _____ (the) long view _____ (be) _____ (a) _____ recurrent _____ (theme) in _____ (the) _____ history of _____ (institutional) _____ (mismanagement) — _____ (sacrifice) _____ (long-term) _____ (sustainability) for _____ (short-term) _____ (gain) is _____ (a) _____ _____ (pattern) whose _____ (cost) _____ (recognize/eventually/passive) but _____ (rarely) _____ (anticipate/passive).','failure / to take / the / long view / is / a / recurrent / theme / the / history / institutional / mismanagement / sacrificing / long-term / sustainability / short-term / gain / a / pattern / costs / are eventually recognized / rarely / anticipated',NULL,'''Failure to take the long view'' + ''sacrificing sustainability for gain is a pattern whose costs are recognized.''','hard'),

  -- BLOCK 78: Gerúndio e infinitivo em estruturas passivas e complexas
  (cid,78,269,'gap_fill','The proposal _____ (deserve) _____ (take) seriously despite _____ (its) _____ _____ (imperfection) — _____ (dismiss) it out of hand _____ (be) _____ (the) _____ kind of _____ (intellectual) _____ (laziness) that _____ (prevent) _____ (the) _____ (field) from _____ (make) _____ (progress) on _____ (genuinely) _____ (difficult) _____ (question).','deserves / being taken / its / imperfections / dismissing / is / the / intellectual / laziness / prevents / the / field / making / progress / genuinely / difficult / questions',NULL,'''Deserves being taken seriously'' (passive gerund) + ''dismissing is a kind of laziness that prevents making progress.''','hard'),
  (cid,78,270,'gap_fill','The evidence _____ (accumulate/passive) over several decades suggests that _____ (invest) in _____ (early) _____ (childhood) _____ (education) is among _____ (the) _____ most cost-effective _____ (strategy) for _____ (achieve) _____ (long-term) _____ (improvement) in _____ (social) _____ (outcome).','accumulated / investing / early / childhood / education / the / strategies / achieving / long-term / improvements / social / outcomes',NULL,'''Investing in early childhood education is among the most cost-effective strategies for achieving improvements.''','medium'),
  (cid,78,271,'gap_fill','Having _____ (fail) _____ (secure) _____ (the) _____ necessary _____ (support) before _____ (launch) _____ (the) _____ initiative, _____ (the) _____ team _____ (find) itself _____ (compel/passive) _____ (operate) without _____ (the) _____ _____ (resources) needed for _____ (implement) _____ (it) effectively.','failed / to secure / the / necessary / support / launching / the / initiative / the / team / found / compelled / to operate / the / resources / implementing / it',NULL,'''Having failed to secure support before launching'' + ''compelled to operate without resources for implementing.''','hard'),
  (cid,78,272,'gap_fill','The _____ (practice) of _____ (set) _____ (measurable) _____ (target) for _____ (achieve) _____ (facilitate) _____ (both) _____ (monitor) and _____ (accountability) — _____ (it) _____ (allow) _____ (stakeholder) _____ (judge) whether _____ (commit) _____ (fulfill/passive) _____ (have) and _____ (enable) _____ (correct) _____ (action) _____ (take/passive) _____ (if/not).','practice / setting / measurable / targets / achieving / facilitates / both / monitoring / accountability / it / allows / stakeholders / to judge / whether / commitments / have been fulfilled / enables / corrective / action / to be taken / if not',NULL,'''Practice of setting measurable targets for achieving'' + ''allows stakeholders to judge whether commitments have been fulfilled.''','hard'),
  (cid,78,273,'gap_fill','The risk of _____ (be/see) _____ (as/partial) _____ (lead) many _____ (researcher) _____ (avoid) _____ (engage) with _____ (question) that _____ (have) _____ (clear) _____ (policy) _____ (implication) — _____ (a) _____ tension _____ (between) _____ (rigorous) _____ (inquiry) and _____ (relevance) that _____ (resolve/difficult/passive) _____ (be).','being seen / as partial / leads / researchers / to avoid / engaging / questions / have / clear / policy / implications / a / tension / between / rigorous / inquiry / relevance / is difficult to resolve',NULL,'''Risk of being seen as partial leads researchers to avoid engaging'' + ''tension difficult to resolve.''','hard'),
  (cid,78,274,'multiple_choice','Which sentence MOST correctly uses a complex gerund structure?','Having invested substantial resources in building the capacity to implement the reform, the organization was unwilling to abandon it before giving it a fair chance to demonstrate results.','["Having been investing substantial resources in building capacity, the organization was unwilling to abandon it.","Having invested substantial resources in building the capacity to implement the reform, the organization was unwilling to abandon it before giving it a fair chance to demonstrate results.","Having substantial resources invested in building the capacity, the organization was unwilling to abandon it.","With having invested substantial resources in building the capacity, the organization was unwilling to abandon it."]','''Having invested...in building...unwilling...before giving it a fair chance to demonstrate'' = most complete and correct complex gerund phrase.','hard'),
  (cid,78,275,'gap_fill','The _____ _____ (experience) of _____ _____ (observe) _____ _____ (institution) _____ _____ (lose) their _____ _____ (effectiveness) over time _____ _____ (shape) _____ _____ the _____ _____ (researcher''s) _____ _____ (interest) in _____ _____ (understand) _____ _____ (the) _____ _____ (mechanism) through _____ which _____ _____ institutional _____ _____ (decline) _____ _____ (occur).','experience / observing / institutions / lose / effectiveness / shaped / the / researcher''s / interest / understanding / the / mechanisms / which / institutional / decline / occurs',NULL,'''Experience of observing institutions lose effectiveness'' + ''shaped interest in understanding mechanisms.''','hard'),
  (cid,78,276,'gap_fill','_____ _____ (know) which _____ _____ (question) _____ _____ (ask) and _____ _____ (which) _____ _____ (ignore) is _____ _____ (as) _____ _____ (important) _____ _____ (as) _____ _____ (know) how _____ _____ _____ to _____ _____ (answer) them — _____ _____ (the) _____ _____ (former) _____ _____ (define) _____ _____ (the) _____ _____ (scope) of _____ _____ (inquiry) while _____ _____ (the) _____ _____ (latter) _____ _____ (determine) _____ _____ (its) _____ _____ (depth).','Knowing / which / questions / to ask / which / to ignore / as / important / as / knowing / how / answer / the / former / defines / the / scope / inquiry / the / latter / determines / its / depth',NULL,'''Knowing which questions to ask/which to ignore'' = complex gerund + infinitives for epistemological argument.','hard'),

  -- BLOCK 79: Produção avançada
  (cid,79,277,'production','[TOEFL Writing — 200 words] Write a paragraph on why institutions tend to resist change, using gerunds and infinitives throughout.','',NULL,'Understanding why institutions resist change requires examining how the people within them perceive and respond to proposals for reform. Most institutions develop routines, norms, and relationships that make existing ways of doing things comfortable and familiar, and disrupting them involves accepting costs that are immediate and certain in exchange for benefits that are deferred and uncertain. Asking individuals to change established practices means asking them to give up the competence they have accumulated over time and to accept the discomfort of learning new ways of doing things, without any guarantee that the new approaches will produce better outcomes. Beyond individual psychology, institutions develop political economies in which those who benefit from existing arrangements acquire interests in maintaining them and the capacity to resist attempts at changing them. Overcoming this resistance without generating counterproductive opposition requires consulting the affected parties early and genuinely engaging with their concerns, rather than treating consultation as a procedural requirement to be satisfied without actually allowing it to influence the design. It also requires demonstrating — preferably through piloting on a small scale before committing to full implementation — that the proposed changes will actually work, so that the argument for accepting the disruption of reform is grounded in evidence rather than in assertions. Failing to do these things systematically is why so many well-designed reforms underperform when implemented.','hard'),
  (cid,79,278,'production','[TOEFL Writing — 200 words] Write a body paragraph on how to build a research program that contributes meaningfully to policy, using gerunds and infinitives.','',NULL,'Building a research program that contributes meaningfully to policy requires making deliberate choices at every stage, from selecting questions to designing methods to communicating findings. Choosing questions that matter to practitioners — that address the uncertainties that actually constrain decision-making rather than the puzzles that are interesting to researchers — is perhaps the most important and most neglected step. Many researchers choose to study questions because they are tractable given available methods and data, rather than because answering them would help anyone make better decisions, and the result is a literature that is methodologically sophisticated but practically irrelevant. Assuming that rigorous methods are sufficient to ensure policy relevance ignores the extent to which relevance must be built in from the beginning. Designing studies that generate actionable evidence — evidence that tells decision-makers not just whether something works in principle but whether it is likely to work in their specific context — requires a level of engagement with practice that most academic research does not involve. And disseminating findings effectively requires investing in communication that reaches the people who need it, not just publishing in journals whose audiences are other researchers. None of this is easy — doing it well while also producing work that meets the standards of rigorous academic inquiry is genuinely difficult. But refusing to try, and instead treating the gap between research and practice as someone else''s problem to solve, ensures that the potential contribution of good research goes unrealized.','hard'),
  (cid,79,279,'gap_fill','[TOEFL Writing] _____ _____ (succeed) _____ _____ (in) _____ _____ (change) how _____ _____ (an) _____ institution _____ _____ (operate) _____ _____ (require) _____ _____ (more) than _____ _____ (issue) _____ _____ (new) _____ _____ (rule) — it _____ _____ (require) _____ _____ (reshape) the _____ _____ (incentive) and _____ _____ (norm) that _____ _____ (govern) _____ _____ (behavior) at _____ _____ (every) _____ _____ (level).','Succeeding / in / changing / an / institution / operates / requires / more / issuing / new / rules / requires / reshaping / incentives / norms / govern / behavior / every / level',NULL,'''Succeeding in changing requires more than issuing rules — requires reshaping incentives.''','hard'),
  (cid,79,280,'gap_fill','[TOEFL Writing] The _____ _____ (key) _____ _____ (challenge) is not _____ _____ (know) what _____ _____ (change) _____ _____ (need) _____ _____ (make) but _____ _____ (figure) out _____ _____ (how) _____ _____ (build) _____ _____ (the) _____ _____ (political) _____ _____ (coalition) _____ _____ (necessary) _____ _____ (sustain) it through _____ _____ (implementation).','key / challenge / knowing / changes / need / to be made / figuring / out / how / to build / the / political / coalition / necessary / to sustain / implementation',NULL,'''Not knowing what changes need to be made but figuring out how to build the coalition necessary to sustain.''','hard'),

  -- BLOCK 80: Exercícios finais
  (cid,80,281,'gap_fill','[TOEFL Writing] The goal of _____ _____ (produce) _____ _____ (actionable) _____ _____ (knowledge) _____ _____ (require) _____ _____ (accept) that _____ _____ (engage) with _____ _____ (practice) sometimes _____ _____ (compromise) the _____ _____ (kind) of _____ _____ (control) that _____ _____ (make) _____ _____ (for) _____ _____ (methodological) _____ _____ (purity).','producing / actionable / knowledge / requires / accepting / that / engaging / practice / compromises / kind / control / makes / for / methodological / purity',NULL,'''Goal of producing requires accepting that engaging compromises control that makes for purity.''','hard'),
  (cid,80,282,'gap_fill','[TOEFL Writing] _____ _____ (demonstrate) that _____ _____ (an) _____ intervention _____ _____ (work) _____ _____ (in) _____ _____ (controlled) _____ _____ (condition) _____ _____ (fall) far _____ _____ (short) of _____ _____ (establish) that it will _____ _____ (work) when _____ _____ (scale/passive) and _____ _____ (implement/passive) in _____ _____ (the) _____ _____ (diverse) and _____ _____ (complex) _____ _____ (context) of _____ _____ (real) _____ _____ (policy).','Demonstrating / that / an / intervention / works / in / controlled / conditions / falls / far / short / establishing / work / scaled / implemented / the / diverse / complex / contexts / real / policy',NULL,'''Demonstrating works in controlled conditions falls short of establishing will work when scaled.''','hard'),
  (cid,80,283,'gap_fill','[TOEFL Writing] _____ _____ (understand) the _____ _____ (world) _____ _____ (well/enough) _____ _____ (act) _____ _____ (on) it wisely is a permanent _____ _____ (challenge) — _____ _____ (one) _____ _____ (that) _____ _____ (require) _____ _____ (continue) _____ _____ (invest) in _____ _____ (both) _____ _____ (research) _____ _____ (and) _____ _____ (the) _____ _____ (institutional) _____ _____ (capacity) _____ _____ (translate) that _____ _____ (research) into _____ _____ (action).','Understanding / the / world / well enough / to act / on / permanent / challenge / one / that / requires / continuing / investing / in / both / research / and / the / institutional / capacity / to translate / research / action',NULL,'''Understanding the world well enough to act on it wisely is a challenge requiring continuing investing.''','hard'),
  (cid,80,284,'gap_fill','[TOEFL Writing] _____ _____ (argue) _____ _____ (convincingly) _____ _____ (for) _____ _____ (a) _____ _____ (position) _____ _____ (and) _____ _____ (acknowledge) _____ _____ (honestly) _____ _____ (its) _____ _____ (limitation) are _____ _____ (not) _____ _____ (incompatible) — _____ _____ (in) _____ _____ (fact), _____ _____ (do) _____ _____ (both) _____ _____ (is) what _____ _____ (distinguish) _____ _____ (rigorous) _____ _____ (scholarship) from _____ _____ (advocacy).','Arguing / convincingly / for / a / position / and / acknowledging / honestly / its / limitations / not / incompatible / in / fact / doing / both / is / distinguishes / rigorous / scholarship / advocacy',NULL,'''Arguing convincingly and acknowledging honestly are not incompatible — doing both distinguishes scholarship from advocacy.''','hard'),
  (cid,80,285,'gap_fill','[TOEFL Writing] The _____ _____ (ability) _____ _____ (recognize) what _____ _____ (one) does not know is at _____ _____ (least) as _____ _____ (important) as _____ _____ (the) _____ _____ (ability) _____ _____ (synthesize) what _____ _____ (one) does — _____ _____ (good) _____ _____ (scholarship) _____ _____ (require) _____ _____ (develop) _____ _____ (both).','ability / to recognize / one / least / important / as / the / ability / to synthesize / one / does / good / scholarship / requires / developing / both',NULL,'''Ability to recognize what one does not know'' + ''ability to synthesize'' + ''scholarship requires developing both.''','medium'),
  (cid,80,286,'multiple_choice','Which sentence MOST successfully combines gerunds and infinitives for a formal academic conclusion?','Achieving the potential that this reform promises requires committing to sustained implementation while remaining willing to adjust the approach in light of evidence about what is and is not working.','["To achieve the potential of this reform requires committing to sustained implementation and to remain willing to adjust.","Achieving the potential that this reform promises requires committing to sustained implementation while remaining willing to adjust the approach in light of evidence about what is and is not working.","To achieve the potential of this reform requires to commit to sustained implementation while remaining willing to adjust.","Achieving the potential requires committing to sustained implementation and remaining willing to adjust."]','Full sentence: ''Achieving potential requires committing to implementation while remaining willing to adjust in light of evidence.''','hard'),
  (cid,80,287,'gap_fill','[TOEFL Writing] _____ _____ (face) _____ _____ (with) _____ _____ (the) _____ _____ (reality) that _____ _____ (simple) _____ _____ (solution) rarely _____ _____ (suffice), _____ _____ (the) most _____ _____ (productive) _____ _____ (response) is _____ _____ (not) _____ _____ (retreat) _____ _____ (into) _____ _____ (despair) but _____ _____ (commit) _____ _____ (to) _____ _____ (understand) _____ _____ (the) _____ _____ (complexity) _____ _____ (well/enough) _____ _____ (navigate) _____ _____ (it) more _____ _____ (wisely).','Faced / with / the / reality / that / simple / solutions / rarely / suffice / the / most / productive / response / is / not / to retreat / into / despair / but / to commit / to / understanding / the / complexity / well enough / to navigate / it / wisely',NULL,'''Faced with the reality'' + ''not to retreat but to commit to understanding well enough to navigate.''','hard'),
  (cid,80,288,'production','[TOEFL Writing — Final 200 words] Write a concluding paragraph on what it means to learn from experience, using gerunds and infinitives throughout.','',NULL,'Learning from experience is not a passive process — it requires actively seeking out what went wrong, committing to understanding why, and accepting the implications of that understanding even when they are uncomfortable. Most organizations claim to learn from experience; far fewer actually do it. The difference lies not in the presence or absence of review processes — most organizations have those — but in the culture that surrounds them. In organizations that genuinely learn, admitting mistakes is treated as the beginning of improvement, not as an occasion for assigning blame. Analyzing what went wrong is something people want to do rather than something they fear doing. Changing practice in response to what analysis reveals is expected and rewarded rather than treated as an admission of prior error. And sharing what has been learned across teams and over time is built into how the organization operates, rather than being left to individuals to do informally. Achieving this kind of culture requires more than communicating a commitment to learning from the top — it requires demonstrating through concrete decisions about who gets promoted, what gets celebrated, and what gets penalized that learning and improving are genuinely valued. Organizations that manage to do this develop a capacity for sustained improvement that those that do not cannot match — and the difference compounds over time.','hard'),
  (cid,80,289,'gap_fill','[TOEFL Writing] The _____ _____ (obligation) _____ _____ (learn) from _____ _____ (the) _____ _____ (past) _____ _____ (carry) _____ _____ (with) _____ _____ (it) _____ _____ (the) _____ _____ (obligation) _____ _____ (act) on _____ _____ (what) has _____ _____ (learn/passive) — _____ _____ (know) without _____ _____ (act) is _____ _____ (incomplete) _____ _____ (at) _____ _____ (best) and _____ _____ (irresponsible) at _____ _____ (worst).','obligation / to learn / from / the / past / carries / with / it / the / obligation / to act / on / what / been learned / knowing / acting / incomplete / at / best / irresponsible / worst',NULL,'''Obligation to learn carries the obligation to act on what has been learned — knowing without acting is incomplete.''','hard'),
  (cid,80,290,'gap_fill','[TOEFL Writing] _____ _____ (do) _____ _____ (the) _____ _____ (work) _____ _____ (well) _____ _____ (matter) _____ _____ (more) _____ _____ (than) _____ _____ (claim) _____ _____ (credit) _____ _____ (for) _____ _____ (do) _____ _____ (it) — a _____ _____ (distinction) _____ _____ (that) _____ _____ (separate) _____ _____ (those) _____ _____ (commit) _____ _____ (to) _____ _____ (serve) _____ _____ (the) _____ _____ (mission) from _____ _____ (those) _____ _____ (commit) _____ _____ (to) _____ _____ (serve) _____ _____ (themselves).','Doing / the / work / well / matters / more / than / claiming / credit / for / doing / it / distinction / that / separates / those / committed / to / serving / the / mission / those / committed / to / serving / themselves',NULL,'''Doing the work well matters more than claiming credit for doing it'' for academic integrity conclusion.','medium'),

  -- BLOCK 78 extra — continuação até 300
  (cid,78,291,'production','[TOEFL Speaking — 45s] Discuss what it means for a research finding to be ''robust'' using gerunds and infinitives throughout.','',NULL,'A research finding qualifies as robust if it meets several demanding criteria simultaneously. First, obtaining the same result across multiple independent studies using different methods and samples provides the most basic form of robustness. Second, maintaining the result even when alternative analytical choices are made — different control variables included, different time periods examined, different outcome measures used — demonstrates that the finding is not an artifact of specific analytical decisions. Third, being able to predict the finding in advance, rather than discovering it in retrospective analysis, strengthens the claim that the observed pattern reflects something real rather than chance. Fourth, having a compelling theoretical explanation that connects the finding to underlying mechanisms that are independently plausible prevents treating a statistical correlation as if it constituted evidence for a specific causal story. And finally, being willing to pre-register the analysis — committing to the specific hypotheses and methods before seeing the data — allows others to evaluate whether the finding emerged from genuine hypothesis testing or from extensive searching for patterns that the data happens to contain. Claiming robustness without meeting these criteria is something that reviewers and readers of research should treat skeptically.','hard'),
  (cid,78,292,'gap_fill','[TOEFL Writing] Having _____ _____ (consider) _____ _____ (the) _____ _____ (full) _____ _____ (range) _____ _____ (of) _____ _____ (evidence), _____ _____ (the) _____ _____ (analyst) _____ _____ (is) _____ _____ (oblige) _____ _____ (acknowledge) _____ _____ (the) _____ _____ (possibility) _____ _____ (of) _____ _____ (being) _____ _____ (wrong) — _____ _____ (refuse) _____ _____ (do) _____ _____ (so) _____ _____ (cross) _____ _____ (the) _____ _____ (line) _____ _____ (between) _____ _____ (advocacy) and _____ _____ (scholarship).','Having / considered / the / full / range / of / evidence / the / analyst / is / obliged / to acknowledge / the / possibility / of / being / wrong / refusing / to do / so / crosses / the / line / between / advocacy / scholarship',NULL,'''Having considered, the analyst is obliged to acknowledge'' + ''refusing to do so crosses the line.''','hard'),
  (cid,78,293,'gap_fill','[TOEFL Writing] _____ _____ (succeed) at _____ _____ (institutional) _____ _____ (reform) _____ _____ (while) _____ _____ (maintain) _____ _____ (the) _____ _____ (support) _____ _____ (of) _____ _____ (those) _____ _____ (most) _____ _____ (affect) _____ _____ (by) _____ _____ (it) _____ _____ (demand) _____ _____ (genuine) _____ _____ (engagement) rather than _____ _____ (mere) _____ _____ (consultation).','Succeeding / at / institutional / reform / while / maintaining / the / support / of / those / most / affected / by / it / demands / genuine / engagement / mere / consultation',NULL,'''Succeeding at reform while maintaining support demands genuine engagement rather than mere consultation.''','hard'),
  (cid,78,294,'gap_fill','[TOEFL Writing] _____ _____ (balance) _____ _____ (ambition) _____ _____ (and) _____ _____ (realism) in _____ _____ (set) _____ _____ (institutional) _____ _____ (goal) _____ _____ (is) _____ _____ (among) _____ _____ (the) _____ _____ (most) _____ _____ (difficult) _____ _____ (judgment) _____ _____ (call) _____ _____ (in) _____ _____ (the) _____ _____ (design) _____ _____ (of) _____ _____ (reform) — _____ _____ (aim) _____ _____ (too) _____ _____ (high) _____ _____ (risk) _____ _____ (fail), _____ _____ (aim) _____ _____ (too) _____ _____ (low) _____ _____ (guarantee) _____ _____ (under-deliver).','Balancing / ambition / and / realism / in / setting / institutional / goals / is / among / the / most / difficult / judgment / calls / in / the / design / of / reform / aiming / too / high / risks / failing / aiming / too / low / guarantees / under-delivering',NULL,'''Balancing ambition in setting goals is among the most difficult calls'' + ''aiming too high risks failing; aiming too low guarantees under-delivering.''','hard'),
  (cid,78,295,'production','[TOEFL Writing — 200 words] Write a paragraph on the challenges of using evidence to inform policy, using gerunds and infinitives throughout.','',NULL,'Using evidence to inform policy involves navigating a set of challenges that are easy to underestimate. Producing evidence of sufficient quality to support confident policy recommendations requires time, resources, and methodological sophistication that are rarely available on the timescales that policy processes demand. Translating findings from the research settings in which they were generated to the real-world contexts in which policy must be implemented involves accepting uncertainty about whether the conditions that made the evidence valid still hold. Communicating findings in ways that are both honest about their limitations and sufficiently clear to be useful to non-specialists requires skills that most researchers have not developed. Competing with other narratives in an information environment saturated with claims of varying credibility makes it harder to ensure that solid evidence gets the attention it deserves. And sustaining the political will to act on evidence once a policy window has opened long enough to actually implement something requires building coalitions that include actors whose commitment to the evidence may be conditional on whether it supports their preferred conclusions. None of these challenges makes using evidence to inform policy impossible — but underestimating them is one of the main reasons that advocates for evidence-based policy are often disappointed by what actually happens when evidence meets politics.','hard'),
  (cid,78,296,'gap_fill','[TOEFL Writing] The _____ _____ (challenge) _____ _____ (of) _____ _____ (remain) _____ _____ (relevant) _____ _____ (while) _____ _____ (maintain) _____ _____ (intellectual) _____ _____ (integrity) _____ _____ (face/passive) _____ _____ (by) _____ _____ (every) _____ _____ (scholar) _____ _____ (work) _____ _____ (on) _____ _____ (consequential) _____ _____ (question) — _____ _____ (resolve) _____ _____ (it) _____ _____ (well) _____ _____ (require) _____ _____ (refuse) _____ _____ (to) _____ _____ (allow) _____ _____ (either) _____ _____ (demand) _____ _____ (cancel) _____ _____ (the) _____ _____ (other).','challenge / of / remaining / relevant / while / maintaining / intellectual / integrity / is faced / by / every / scholar / working / on / consequential / questions / resolving / it / well / requires / refusing / to / allow / either / demand / cancel / the / other',NULL,'''Challenge of remaining relevant while maintaining integrity'' + ''resolving it well requires refusing to allow either to cancel the other.''','hard'),
  (cid,78,297,'production','[TOEFL Writing — 200 words] Write a conclusion on what distinguishes good scholarship from mere advocacy, using gerunds and infinitives throughout.','',NULL,'Distinguishing good scholarship from advocacy involves attending to several markers that are visible at the level of both method and rhetoric. In terms of method, good scholarship commits to following the evidence wherever it leads, even when the conclusions are uncomfortable or inconvenient for the researcher''s prior views. It involves seeking out evidence that could disconfirm the argument being developed, not just evidence that supports it. It requires acknowledging the limitations of available evidence honestly rather than minimizing them in order to project a confidence that the data cannot warrant. And it demands transparency about the choices made in analyzing the data — the assumptions built into the methods, the alternative analyses that were considered and rejected, the specification decisions that shaped the results. In terms of rhetoric, good scholarship avoids overstating conclusions beyond what the evidence supports and avoids framing findings in ways designed to generate a predetermined reader response rather than to communicate what was actually found. The test is whether a reader who disagrees with the author''s conclusions could nonetheless find the analysis useful for developing their own, because the evidence, methods, and reasoning are presented clearly enough to allow independent evaluation. Meeting this test is what separates scholarship from advocacy, and committing to meet it is the basic obligation of anyone who claims to be engaged in the pursuit of knowledge.','hard'),
  (cid,78,298,'gap_fill','[TOEFL Writing] In _____ _____ (sum), _____ _____ (produce) _____ _____ (knowledge) _____ _____ (that) _____ _____ (endure) _____ _____ (require) _____ _____ (more) _____ _____ (than) _____ _____ (master) _____ _____ (the) _____ _____ (technical) _____ _____ (skill) _____ _____ (of) _____ _____ (one''s) _____ _____ (discipline) — _____ _____ (it) _____ _____ (require) _____ _____ (commit) _____ _____ (to) _____ _____ (ask) _____ _____ (the) _____ _____ (right) _____ _____ (question) and _____ _____ (pursue) _____ _____ (them) _____ _____ (with) _____ _____ (integrity).','In / sum / producing / knowledge / that / endures / requires / more / than / mastering / the / technical / skills / of / one''s / discipline / it / requires / committing / to / asking / the / right / questions / pursuing / them / with / integrity',NULL,'''Producing knowledge requires more than mastering skills — requires committing to asking right questions.''','medium'),
  (cid,78,299,'gap_fill','[TOEFL Writing] _____ _____ (the) _____ _____ (purpose) _____ _____ (of) _____ _____ (scholarship) _____ _____ (is) _____ _____ (to) _____ _____ (advance) _____ _____ (understanding), _____ _____ (then) _____ _____ (succeed) _____ _____ (in) _____ _____ (do) _____ _____ (so) _____ _____ (means) _____ _____ (change) _____ _____ (how) _____ _____ (people) _____ _____ (think) — _____ _____ (and) _____ _____ (that) _____ _____ (is) _____ _____ (a) _____ _____ (standard) _____ _____ (far) _____ _____ (more) _____ _____ (demand) _____ _____ (than) _____ _____ (merely) _____ _____ (publish).','If the / purpose / of / scholarship / is / to / advance / understanding / then / succeeding / in / doing / so / means / changing / how / people / think / and / that / is / a / standard / far / more / demanding / than / merely / publishing',NULL,'''If purpose is to advance understanding, then succeeding means changing how people think."','medium'),
  (cid,78,300,'production','[TOEFL Writing — Final 200 words] Write a final capstone paragraph on why investing in institutional quality matters, using gerunds and infinitives throughout.','',NULL,'Investing in institutional quality is one of the most consequential choices that any society can make. Doing so well requires understanding that institutions are not simply technical arrangements for delivering services — they are the frameworks through which collective life is organized, the mechanisms through which power is allocated and constrained, and the vessels in which the accumulated trust and legitimacy of generations of governance is carried forward. Allowing them to deteriorate by failing to invest in their maintenance, by tolerating the erosion of the norms that make them function, or by permitting the capture of their leadership by interests antithetical to their purposes is not merely a technical failure — it is a failure of the most basic obligation that one generation has to the next. Building and maintaining effective institutions is slow, demanding, and often invisible work whose returns accrue over decades rather than electoral cycles. The difficulty of measuring it, crediting it, and rewarding those who do it well is part of why it is so often neglected. But recognizing this neglect and committing to address it — accepting the discipline of investing consistently in what matters most, even when the returns are deferred and the temptation to spend the savings is acute — is precisely what distinguishes societies capable of sustaining high-quality governance from those condemned to perpetual institutional fragility. That is the argument; the rest is implementation.','hard')

